#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static void append(char **s, size_t *n, const char *t) {
    size_t k = strlen(t);
    *s = (char *)realloc(*s, *n + k + 1);
    memcpy(*s + *n, t, k + 1);
    *n += k;
}
static bool match(const char *s, const char *p, unsigned f) {
    size_t n = strlen(s), k = strlen(p);
    if (f & GREP_WHOLE) {
        while (n && (s[n - 1] == '\n' || s[n - 1] == '\n'))
            n--;
        if (n != k)
            return false;
    }
    for (size_t i = 0; i + k <= n; i++) {
        bool ok = true;
        for (size_t j = 0; j < k; j++) {
            int a = (unsigned char)s[i + j], b = (unsigned char)p[j];
            if (f & GREP_IGNORE_CASE) {
                a = tolower(a);
                b = tolower(b);
            }
            if (a != b) {
                ok = false;
                break;
            }
        }
        if (ok)
            return true;
        if (f & GREP_WHOLE)
            break;
    }
    return false;
}
char *grep(const char *p, unsigned f, const char *const *files, size_t count) {
    char *out = (char *)calloc(1, 1);
    size_t len = 0;
    for (size_t k = 0; k < count; k++) {
        FILE *fp = fopen(files[k], "r");
        if (!fp)
            continue;
        size_t line_number = 0;
        for (;;) {
            char *line = (char *)calloc(1, 1);
            size_t n = 0;
            int c;
            while ((c = fgetc(fp)) != EOF) {
                char t[2] = {(char)c, 0};
                append(&line, &n, t);
                if (c == '\n')
                    break;
            }
            if (!n) {
                free(line);
                break;
            }
            line_number++;
            bool yes = match(line, p, f);
            if (f & GREP_INVERT)
                yes = !yes;
            if (yes) {
                if (f & GREP_FILES) {
                    append(&out, &len, files[k]);
                    append(&out, &len, "\n");
                    free(line);
                    break;
                }
                if (count > 1) {
                    append(&out, &len, files[k]);
                    append(&out, &len, ":");
                }
                if (f & GREP_NUMBER) {
                    char num[40];
                    snprintf(num, 40, "%zu:", line_number);
                    append(&out, &len, num);
                }
                append(&out, &len, line);
            }
            free(line);
        }
        fclose(fp);
    }
    return out;
}

