#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    FILE *f = fopen("grep-test.txt", "w");
    assert(f);
    fputs("Hello\nworld\nHELLO there\n", f);
    fclose(f);
    const char *files[] = {"grep-test.txt"};
    char *s = grep("hello", GREP_IGNORE_CASE | GREP_NUMBER, files, 1);
    assert(!strcmp(s, "1:Hello\n3:HELLO there\n"));
    free(s);
    s = grep("Hello", GREP_WHOLE, files, 1);
    assert(!strcmp(s, "Hello\n"));
    free(s);
    s = grep("Hello", GREP_INVERT, files, 1);
    assert(strstr(s, "world"));
    free(s);
    s = grep("world", GREP_FILES, files, 1);
    assert(!strcmp(s, "grep-test.txt\n"));
    free(s);
    remove("grep-test.txt");

    return 0;
}
